# Câu 31–35 (viết lại câu, viết câu từ từ gợi ý) = essay 3 dòng, đáp án mẫu trong explanation.
# LƯU Ý đáp án gốc: câu 13 bảng đáp án ghi C (tablespoon) nhưng lời giải chi tiết chọn A (teaspoon) – dùng A (teaspoon) vì 'only a teaspoon of sugar' hợp lý với một cốc cà phê; câu 12 lời giải chi tiết ghi 'Chọn B' nhưng bảng đáp án và nội dung giải thích đều là D (box) – dùng D.
# Câu nghi ngờ nhẹ: câu 12 'a bag of chocolates' cũng có thể nói được, nhưng chọn 'box' theo đáp án gốc (hộp sô-cô-la dùng làm quà tặng).
